#include <vector>

class Solution {
public:
    std::vector<int> decompressRLElist(std::vector<int>& nums) {
        std::vector<int> res;
        for (size_t i = 0; i < nums.size(); i += 2) {
            int freq = nums[i], val = nums[i + 1];
            res.insert(res.end(), freq, val);
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public int[] decompressRLElist(int[] nums) {
        int totalLen = 0;
        for (int i = 0; i < nums.length; i += 2) totalLen += nums[i];
        int[] res = new int[totalLen];
        int idx = 0;
        for (int i = 0; i < nums.length; i += 2) {
            int freq = nums[i], val = nums[i + 1];
            for (int k = 0; k < freq; k++) res[idx++] = val;
        }
        return res;
    }
}

var decompressRLElist = function(nums) {
    const res = [];
    for (let i = 0; i < nums.length; i += 2) {
        const freq = nums[i], val = nums[i + 1];
        for (let k = 0; k < freq; k++) res.push(val);
    }
    return res;
};
